"""Glossaire propre N18, Cycle 2; aucune validation médicale humaine."""
G = {'MRC': {'lit': [['MRC', 'Maladie rénale chronique']], 'full': 'Maladie rénale chronique', 'def': '<p>Anomalie de structure ou de fonction rénale ayant une implication sanitaire, présente au moins trois mois ou avec preuve suffisante de chronicité.</p>', 'ref': 'n18-chronologie'}, 'DFG': {'lit': [['DFG', 'Débit de filtration glomérulaire']], 'full': 'Débit de filtration glomérulaire', 'def': '<p>Volume de plasma filtré par les glomérules par unité de temps; distinct du volume urinaire final.</p>', 'ref': 'n18-filtration'}, 'DFGe': {'lit': [['DFGe', 'Débit de filtration glomérulaire estimé']], 'full': 'Débit de filtration glomérulaire estimé', 'def': '<p>Résultat d’une équation utilisant un ou plusieurs marqueurs; version, unités et limites doivent accompagner le nombre.</p>', 'ref': 'n18-dfg'}, 'ACR': {'lit': [['ACR', 'Albumin-to-creatinine ratio; rapport albumine/créatinine']], 'full': 'Albumin-to-creatinine ratio; rapport albumine/créatinine', 'def': '<p>Rapport urinaire en mg/mmol ou mg/g, à interpréter avec les unités et le contexte du prélèvement.</p>', 'ref': 'n18-acr'}, 'KDIGO': {'lit': [['KDIGO', 'Kidney Disease: Improving Global Outcomes']], 'full': 'Kidney Disease: Improving Global Outcomes', 'def': '<p>Organisation internationale de recommandations rénales; ses textes sont distingués des directives américaines et confrontés au contexte suisse.</p>', 'ref': 'n18-a02-fenetre-1'}, 'SSN': {'lit': [['SSN', 'Société suisse de néphrologie']], 'full': 'Société suisse de néphrologie', 'def': '<p>Société à l’origine de la fiche suisse de dépistage et prise en charge du 17 mars 2025 utilisée dans cette leçon.</p>', 'ref': 'n18-recours'}, 'FI': {'lit': [['FI', 'Information professionnelle']], 'full': 'Information professionnelle', 'def': '<p>Texte suisse du produit exact : indication, forme, posologie, restrictions et surveillance.</p>', 'ref': 'n18-p01-fenetre-2'}, 'DCI': {'lit': [['DCI', 'Dénomination commune internationale']], 'full': 'Dénomination commune internationale', 'def': '<p>Nom de la substance active; il ne remplace pas l’identification du produit, du dosage et de la forme.</p>', 'ref': 'n18-p01-fenetre-2'}, 'CKD-EPI': {'lit': [['CKD-EPI', 'Chronic Kidney Disease Epidemiology Collaboration']], 'full': 'Chronic Kidney Disease Epidemiology Collaboration', 'def': '<p>Nom d’équations de filtration; la version créatinine 2021 présentée ici est explicitée à partir du document danois DEKS.</p>', 'ref': 'n18-e01-fenetre-2'}, 'DEKS': {'lit': [['DEKS', 'Service danois d’évaluation de qualité des laboratoires']], 'full': 'Service danois d’évaluation de qualité des laboratoires', 'def': '<p>Organisme publiant le document de calcul d’estimation de filtration daté de mai 2025; son nom est conservé sans inventer un développement non établi dans le PDF lu.</p>', 'ref': 'n18-e01-fenetre-2'}, 'KFRE': {'lit': [['KFRE', 'Kidney Failure Risk Equation']], 'full': 'Kidney Failure Risk Equation', 'def': '<p>Équation du risque de suppléance rénale; population, calibration et horizon doivent être précisés.</p>', 'ref': 'n18-e03-fenetre-2'}, 'SGLT2': {'lit': [['SGLT2', 'Sodium–glucose cotransporter 2']], 'full': 'Sodium–glucose cotransporter 2', 'def': '<p>Cotransporteur sodium–glucose de type 2, cible de la dapagliflozine; le mécanisme ne suffit pas à établir une indication.</p>', 'ref': 'n18-forxiga'}, 'CYP3A4': {'lit': [['CYP3A4', 'Cytochrome P450, famille 3, sous-famille A, isoforme 4']], 'full': 'Cytochrome P450, famille 3, sous-famille A, isoforme 4', 'def': '<p>Enzyme intervenant dans le métabolisme de la finérénone; certains inhibiteurs puissants contre-indiquent son association.</p>', 'ref': 'n18-kerendia'}, 'ADH': {'lit': [['ADH', 'Antidiuretic hormone; hormone antidiurétique']], 'full': 'Antidiuretic hormone; hormone antidiurétique', 'def': '<p>Hormone qui modifie notamment la perméabilité à l’eau du collecteur via les aquaporines, distincte de l’aldostérone.</p>', 'ref': 'n18-s04-fenetre-1'}, 'PAS': {'lit': [['PAS', 'Periodic acid–Schiff; acide périodique–Schiff']], 'full': 'Periodic acid–Schiff; acide périodique–Schiff', 'def': '<p>Coloration histologique utilisée dans la microphotographie de glomérulosclérose publiée; elle ne suffit pas à déterminer la cause clinique.</p>', 'ref': 'n18-s01-fenetre-2'}, 'TGF-β': {'lit': [['TGF-β', 'Transforming growth factor beta']], 'full': 'Transforming growth factor beta', 'def': '<p>Médiateur cité dans les mécanismes profibrosants du document HUG; il ne désigne pas une cause unique de maladie rénale.</p>', 'ref': 'n18-s04-fenetre-2'}, 'Hb': {'lit': [['Hb', 'Hémoglobine']], 'full': 'Hémoglobine', 'def': '<p>Protéine des globules rouges; sa concentration est utilisée dans le bilan et le suivi de l’anémie, avec unités explicites.</p>', 'ref': 'n18-aranesp'}, 'NaCl': {'lit': [['NaCl', 'Chlorure de sodium']], 'full': 'Chlorure de sodium', 'def': '<p>Sel contenant sodium et chlorure; le gramme de sel n’est pas un gramme de sodium.</p>', 'ref': 'n18-s03-fenetre-1'}, 'SI': {'lit': [['SI', 'Système international d’unités']], 'full': 'Système international d’unités', 'def': '<p>Convention d’unités : vérifier notamment µmol/L, mmol/L, mg/mmol et mL/min/1,73 m².</p>', 'ref': 'n18-e01-fenetre-2'}, 'G3': {'lit': [['G3', 'Catégorie de filtration G3']], 'full': 'Catégorie de filtration G3', 'def': '<p>La filtration de 30 à 59 mL/min/1,73 m² comprend G3a et G3b; la durée et les marqueurs complètent le diagnostic.</p>', 'ref': 'n18-dfg'}, 'DAPA-CKD': {'lit': [['DAPA-CKD', 'DAPA-CKD, nom de l’essai dapagliflozine et maladie rénale chronique']], 'full': 'DAPA-CKD, nom de l’essai dapagliflozine et maladie rénale chronique', 'def': '<p>Essai international de dapagliflozine dans une population rénale définie; exclusions et horizon figurent dans la fenêtre du produit.</p>', 'ref': 'n18-forxiga'}, 'GLP-1': {'lit': [['GLP-1', 'Glucagon-like peptide 1']], 'full': 'Glucagon-like peptide 1', 'def': '<p>Hormone incrétine dont le récepteur est la cible du sémaglutide; le mécanisme ne remplace pas l’indication suisse.</p>', 'ref': 'n18-ozempic'}, 'PCSK9': {'lit': [['PCSK9', 'Proprotein convertase subtilisin/kexin type 9']], 'full': 'Proprotein convertase subtilisin/kexin type 9', 'def': '<p>Protéine ciblée par l’evolocumab pour abaisser le cholestérol LDL dans les indications retenues.</p>', 'ref': 'n18-lipides'}}

# Ajouts C02-R-NEPH (Cycle 2) : sous-codes CIM-10-GM 2024 cités dans le texte et noms de présentation,
# ajoutés seulement s'ils sont absents des autres glossaires.
def _add(key, lit, full, definition, window):
    if key not in G:
        G[key] = {'lit': [list(x) for x in lit], 'full': full, 'def': '<p>' + definition + '</p>', 'ref': window}
for _code, _titre, _win in [
        ('N18.1', 'Maladie rénale chronique, stade 1', 'n18-dfg'),
        ('N18.2', 'Maladie rénale chronique, stade 2', 'n18-dfg'),
        ('N18.3', 'Maladie rénale chronique, stade 3', 'n18-dfg'),
        ('N18.4', 'Maladie rénale chronique, stade 4', 'n18-dfg'),
        ('N18.5', 'Maladie rénale chronique, stade 5', 'n18-dfg'),
        ('N18.8', 'Autre néphropathie chronique', 'n18-a10-fenetre-2'),
        ('N18.80', 'Trouble de la fonction rénale, chronique, unilatéral', 'n18-a10-fenetre-1'),
        ('N18.89', 'Autre néphropathie chronique, stade non précisé', 'n18-a10-fenetre-2'),
        ('N18.9', 'Maladie rénale chronique, sans précision', 'n18-a10-fenetre-2')]:
    _add(_code, [(_code, 'Code CIM-10-GM 2024 : ' + _titre)], _titre,
         'Sous-code du catalogue CIM-10-GM 2024 (OFS) : « ' + _titre + ' ». Le libellé administratif ne remplace ni la cause, ni les catégories G et A, ni la preuve de chronicité.', _win)
_add('DualDose', [('DualDose', 'Nom de présentation commerciale du stylo Ozempic, non développable lettre à lettre')],
     'Présentation Ozempic DualDose', 'Nom de présentation du stylo prérempli Ozempic dans l’information professionnelle suisse ; ce n’est pas une abréviation médicale.', 'n18-ozempic')
_add('FixDose', [('FixDose', 'Nom de présentation commerciale du stylo Ozempic, non développable lettre à lettre')],
     'Présentation Ozempic FixDose', 'Nom de présentation du stylo prérempli Ozempic dans l’information professionnelle suisse ; ce n’est pas une abréviation médicale.', 'n18-ozempic')

